SELECT CASE WHEN ss.units >= 43 THEN 'high' WHEN ss.units >= 18 THEN 'mid' ELSE 'low' END AS units_bucket, COUNT(*) AS num_inventory, COUNT(DISTINCT i.quantity) AS unique_products FROM inventory i INNER JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id GROUP BY CASE WHEN ss.units >= 43 THEN 'high' WHEN ss.units >= 18 THEN 'mid' ELSE 'low' END ORDER BY unique_products DESC
